import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'docx', 'odt', 'rtf', 'html', 'md'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename or not allowed_file(uploaded.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    # Read conversion options from request
    options = request.form.get('options', '{}')
    try:
        conv_opts = yaml.safe_load(options)
    except yaml.YAMLError:
        conv_opts = {}

    # Determine output format
    output_format = conv_opts.get('format', 'pdf') if isinstance(conv_opts, dict) else 'pdf'

    # Sanitize format parameter
    if not output_format.isalnum():
        output_format = 'pdf'

    filename = secure_filename(uploaded.filename)
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)
    input_path = os.path.join(work_dir, filename)
    uploaded.save(input_path)

    # Build LibreOffice conversion command
    # User can specify a custom filter via options for advanced conversions
    filter_name = None
    if isinstance(conv_opts, dict) and 'filter' in conv_opts:
        filter_name = conv_opts['filter']

    cmd = ['libreoffice', '--headless', '--convert-to', output_format]

    if filter_name:
        # Allow specifying export filter for advanced use cases
        cmd = ['libreoffice', '--headless', '--convert-to', 
               f'{output_format}:{filter_name}', '--outdir', work_dir, input_path]
    else:
        cmd += ['--outdir', work_dir, input_path]

    try:
        result = subprocess.run(
            cmd,
            timeout=30,
            capture_output=True,
            cwd=work_dir
        )
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504
    except Exception as e:
        return jsonify({'error': f'Conversion failed: {str(e)}'}), 500

    if result.returncode != 0:
        return jsonify({'error': 'LibreOffice conversion error', 
                       'details': result.stderr.decode('utf-8', errors='replace')[:500]}), 500

    # Find output file
    output_ext = output_format.split(':')[0] if ':' in output_format else output_format
    base_name = os.path.splitext(filename)[0]
    output_path = os.path.join(work_dir, f'{base_name}.{output_ext}')

    if not os.path.exists(output_path):
        # Try to find any new file in work_dir
        for f in os.listdir(work_dir):
            if f != filename:
                output_path = os.path.join(work_dir, f)
                break
        else:
            return jsonify({'error': 'Output file not found'}), 500

    return send_file(output_path, as_attachment=True, 
                    download_name=f'{base_name}.{output_ext}')


@app.route('/api/v1/macro-convert', methods=['POST'])
def macro_convert():
    """Convert with macro execution enabled for template processing."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'No filename'}), 400

    filename = secure_filename(uploaded.filename)
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)
    input_path = os.path.join(work_dir, filename)
    uploaded.save(input_path)

    # Macro-enabled conversion for internal template processing
    macro_name = request.form.get('macro', 'Standard.Module1.ConvertToPDF')

    cmd = [
        'libreoffice', '--headless', '--invisible',
        f'macro:///{macro_name}',
        input_path
    ]

    try:
        result = subprocess.run(cmd, timeout=60, capture_output=True, cwd=work_dir)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Macro execution timeout'}), 504

    base_name = os.path.splitext(filename)[0]
    output_path = os.path.join(work_dir, f'{base_name}.pdf')

    if os.path.exists(output_path):
        return send_file(output_path, as_attachment=True, download_name=f'{base_name}.pdf')

    return jsonify({'error': 'Macro conversion produced no output'}), 500


if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
